  "summary": "Intellectual property rights in Company IP created by the executive automatically vest in the company absolutely upon creation, or are assigned by the executive to the company.",
  "evidence": [
    {
      "passage_id": 2,
      "quote": "The Executive acknowledges that all Intellectual Property Rights subsisting (or which may in the future subsist) in such Company IP shall automatically, on creation, vest in the Company absolutely."
    },
    {
      "passage_id": 5,
      "quote": "To the extent that the Company IP does not vest automatically in the Company the Executive hereby assigns all right, title and interest in the Company IP to the Company with full title guarantee by way of a present assignment of all future rights and shall otherwise hold them on trust for the Company."
    }
  ]
}
